// ============================================================
// MineBench Build: A Choo-Choo Train (v9 - cab-first ordering)
// ============================================================

// --- Helpers ---
function cyl(cx, cy, cz, r, h, type) {
  let r2 = r * r;
  for (let dy = -r; dy <= r; dy++) {
    for (let dx = -r; dx <= r; dx++) {
      if (dx * dx + dy * dy <= r2) {
        for (let dz = -Math.floor(r); dz <= Math.floor(r); dz++) {
          block(cx + dx, cy + dy, cz + dz, type);
        }
      }
    }
  }
}

function cylZ(cx, cy, cz, r, h, type) {
  let r2 = r * r;
  for (let dx = -r; dx <= r; dx++) {
    for (let dz = -r; dz <= r; dz++) {
      if (dx * dx + dz * dz <= r2) {
        for (let dy = 0; dy < h; dy++) {
          block(cx + dx, cy + dy, cz + dz, type);
        }
      }
    }
  }
}

function sphere(cx, cy, cz, r, type) {
  let r2 = r * r;
  for (let dy = -r; dy <= r; dy++) {
    for (let dx = -r; dx <= r; dx++) {
      for (let dz = -r; dz <= r; dz++) {
        if (dx * dx + dy * dy + dz * dz <= r2) {
          block(cx + dx, cy + dy, cz + dz, type);
        }
      }
    }
  }
}

function wheel(wx, wy, wz, r, edgeType, hubType) {
  let r2 = r * r;
  for (let dy = -r; dy <= r; dy++) {
    for (let dx = -r; dx <= r; dx++) {
      const dist = dx * dx + dy * dy;
      if (dist <= r2) {
        const isSpoke = Math.abs(dx) <= 1 || Math.abs(dy) <= 1;
        if (Math.abs(dx) <= 2 && Math.abs(dy) <= 2) {
          block(wx + dx, wy + dy, wz, hubType || 'iron_block');
        } else if (dist >= (r - 1) * (r - 1)) {
          block(wx + dx, wy + dy, wz, edgeType || 'iron_block');
        } else if (isSpoke) {
          block(wx + dx, wy + dy, wz, 'iron_block');
        } else {
          block(wx + dx, wy + dy, wz, 'gray_wool');
        }
      }
    }
  }
}

// --- Palette ---
const BLACK = 'black_wool';
const GRAY = 'gray_wool';
const IRON = 'iron_block';
const STONE = 'stone';
const BRICKS = 'bricks';
const OAK = 'oak_planks';
const OAK_LOG = 'oak_log';
const GLASS = 'glass';
const GLOW = 'glowstone';
const GOLD = 'gold_block';
const WHITE = 'white_wool';
const SAND = 'sand';
const DIRT = 'dirt';
const LEAVES = 'oak_leaves';
const BROWN_WOOL = 'brown_wool';
const RED_WOOL = 'red_wool';
const GREEN_WOOL = 'green_wool';

// --- Scenery: trees (ty=0 so trunk reaches y=0, grounded) ---
function tree(tx, ty, tz) {
  for (let dy = 0; dy < 9; dy++) {
    block(tx, ty + dy, tz, OAK_LOG);
  }
  sphere(tx, ty + 8, tz, 3, LEAVES);
  sphere(tx - 1, ty + 7, tz, 2, LEAVES);
  sphere(tx + 1, ty + 7, tz, 2, LEAVES);
  sphere(tx, ty + 9, tz, 2, LEAVES);
}

tree(60, 0, 100);
tree(68, 0, 106);
tree(185, 0, 95);
tree(192, 0, 100);
tree(55, 0, 55);
tree(180, 0, 50);

// --- Ground plane (full coverage: z=45 to 120) ---
for (let x = 50; x <= 210; x++) {
  for (let dz = 45; dz <= 120; dz++) {
    box(x, 0, dz, x, 0, dz, DIRT);
  }
}
for (let x = 50; x <= 210; x++) {
  for (let dz = 45; dz <= 120; dz++) {
    box(x, 1, dz, x, 1, dz, GREEN_WOOL);
  }
}

// --- Track bed ---
const LZ = 85;
const YG = 1;

for (let x = 50; x <= 210; x++) {
  for (let dz = -5; dz <= 5; dz++) {
    box(x, YG, LZ + dz, x, YG, LZ + dz, SAND);
  }
}
for (let x = 53; x <= 207; x += 2) {
  for (let dz = -3; dz <= 3; dz++) {
    box(x, YG, LZ + dz, x, YG, LZ + dz, OAK);
  }
}
for (let x = 50; x <= 210; x++) {
  box(x, YG + 1, LZ - 2, x, YG + 1, LZ - 2, IRON);
  box(x, YG + 1, LZ + 2, x, YG + 1, LZ + 2, IRON);
}

// --- Water tower (far -Z side, legs at corners, grounded)
const wtx = 75, wtz = 45;
for (let dy = 0; dy < 19; dy++) {
  block(wtx - 2, dy, wtz - 2, IRON);
  block(wtx + 2, dy, wtz - 2, IRON);
  block(wtx - 2, dy, wtz + 2, IRON);
  block(wtx + 2, dy, wtz + 2, IRON);
}
for (let dy = 4; dy < 19; dy += 6) {
  line(wtx - 2, dy, wtz - 2, wtx + 2, dy + 3, wtz + 2, IRON);
  line(wtx + 2, dy, wtz - 2, wtx - 2, dy + 3, wtz + 2, IRON);
}
cyl(wtx, 19, wtz, 4, 6, GRAY);
box(wtx - 4, 19, wtz - 1, wtx + 4, 19, wtz + 1, GRAY);
box(wtx - 4, 24, wtz - 1, wtx + 4, 24, wtz + 1, GRAY);
cylZ(wtx, 25, wtz, 3, 1, BRICKS);
cylZ(wtx, 0, wtz, 1, 19, IRON);

// --- Locomotive ---
const LX = 128;
const front = LX + 30;
const back = LX - 25;
const top = 22;
const bot = 4;
const Z = LZ;

// Smokebox
cyl(front + 2, 12, Z, 7, 10, GRAY);
cyl(front + 2, 12, Z, 6, 10, BLACK);

// Smokestack (body extends to y=20 to touch gold trim at y=21)
cylZ(front + 10, bot, Z, 3, 17, BLACK);
cylZ(front + 10, top - 1, Z, 4, 1, GOLD);
cylZ(front + 10, top + 1, Z, 2, 1, GOLD);
cylZ(front + 10, bot - 1, Z, 4, 1, IRON);

// Boiler (tapered)
for (let x = front - 4; x <= back + 2; x++) {
  let t = (x - (front - 4)) / ((back + 2) - (front - 4));
  let r = 7 + 2 * (1 - t);
  cyl(x, 12, Z, Math.round(r), 1, GRAY);
  cyl(x, 12, Z, Math.round(r) - 1, 1, BLACK);
}

// Cab (built FIRST so dome/trim sit on top of it)
box(back - 4, bot, Z - 5, back + 6, top - 1, Z + 5, BLACK);
cyl(back + 1, top - 1, Z - 5, 3, 14, BLACK);
cyl(back + 1, top - 1, Z + 5, 3, 14, BLACK);
cyl(back + 1, top, Z - 3, 2, 10, BLACK);
box(back, top - 4, Z - 5, back + 4, top - 2, Z - 5, GLASS);
box(back, top - 4, Z + 5, back + 4, top - 2, Z + 5, GLASS);

// Boiler dome (sits on cab top: cab ends y=21, dome starts y=21, BLACK to connect to cab)
cylZ(LX - 2, top - 1, Z, 2, 3, BLACK);
box(LX - 2, top + 3, Z - 1, LX - 2, top + 3, Z + 1, GOLD);

// Water tank behind cab (connects cab to tender)
box(back + 7, bot + 1, Z - 4, back + 12, bot + 6, Z + 4, GRAY);
box(back + 7, bot + 7, Z - 3, back + 12, bot + 7, Z + 3, GRAY);
for (let y = bot + 1; y <= bot + 7; y++) {
  box(back + 12, y, Z - 4, back + 12, y, Z - 4, IRON);
}

// Bell
cylZ(LX, top + 1, Z, 1, 2, GOLD);
box(LX - 1, top + 3, Z - 1, LX + 1, top + 3, Z + 1, GOLD);

// Whistle
cylZ(front + 6, bot + 4, Z, 1, 4, GOLD);
box(front + 6, bot + 7, Z - 1, front + 6, bot + 7, Z + 1, GOLD);

// Cowcatcher
for (let dy = 0; dy < 4; dy++) {
  let w = 3 + dy;
  box(front + 10 + dy, bot + dy, Z - w, front + 10 + dy, bot + dy, Z + w, IRON);
}
box(front + 13, bot, Z - 3, front + 13, bot, Z + 3, STONE);
box(front + 13, bot + 1, Z, front + 13, bot + 1, Z, GLOW);

// --- Wheels ---
wheel(front + 2, 8, Z - 5, 8, 'iron_block', 'gold_block');
wheel(front + 2, 8, Z + 5, 8, 'iron_block', 'gold_block');
wheel(LX, 8, Z - 5, 8, 'iron_block', 'gold_block');
wheel(LX, 8, Z + 5, 8, 'iron_block', 'gold_block');

function sWheel(wx, wy, wz) {
  wheel(wx, wy, wz, 5, 'iron_block', 'iron_block');
}
sWheel(front - 10, 5, Z - 5);
sWheel(front - 10, 5, Z + 5);
sWheel(back - 6, 5, Z - 5);
sWheel(back - 6, 5, Z + 5);

// Connecting rods
for (let x = front - 8; x <= front + 10; x++) {
  box(x, 8, Z - 6, x, 8, Z + 6, IRON);
}
for (let x = LX - 6; x <= front + 10; x++) {
  box(x, 8, Z - 6, x, 8, Z + 6, IRON);
}
for (let y = 8; y <= 14; y++) {
  box(front + 4, y, Z - 1, front + 4, y, Z + 1, IRON);
}
box(front + 2, 10, Z - 2, front + 2, 14, Z + 2, GRAY);

// --- Tender ---
const tBack = back - 32;
const tFront = back - 2;
box(tFront, bot, Z - 5, tBack, bot, Z + 5, BLACK);
box(tFront, bot + 1, Z - 4, tBack, bot + 1, Z + 4, OAK);
box(tFront, top - 2, Z - 4, tBack, top - 2, Z + 4, OAK);
box(tFront, bot, Z - 5, tFront, top - 2, Z + 5, BLACK);
box(tBack, bot, Z - 5, tBack, top - 2, Z + 5, BLACK);
// Tender coupling (sturdy, 3-block-wide)
for (let x = tBack; x <= back - 4; x++) {
  box(x, bot + 1, Z - 1, x, bot + 3, Z + 1, IRON);
}

// Coal pile (mounded)
cylZ((tFront + tBack) / 2, bot + 2, Z, 4, 4, BROWN_WOOL);
cylZ((tFront + tBack) / 2, bot + 5, Z, 3, 2, BROWN_WOOL);
sphere((tFront + tBack) / 2, bot + 7, Z, 2, BROWN_WOOL);

// --- Headlight ---
box(front + 9, 14, Z - 1, front + 9, 14, Z + 1, GLOW);
box(front + 10, 14, Z - 1, front + 10, 14, Z + 1, GLASS);
box(front + 8, 13, Z - 2, front + 8, 15, Z + 2, IRON);

// --- Station building (on +Z side of track) ---
const stZ = LZ + 10;
box(165, 2, stZ, 165, 11, stZ + 25, BRICKS);
box(165, 2, stZ + 25, 180, 11, stZ + 25, BRICKS);
box(180, 2, stZ, 180, 11, stZ + 25, BRICKS);
box(163, 12, stZ - 2, 182, 13, stZ + 27, BRICKS);
box(164, 13, stZ - 1, 181, 14, stZ + 26, RED_WOOL);
box(165, 2, stZ + 13, 165, 7, stZ + 17, OAK_LOG);
box(165, 6, stZ + 3, 165, 8, stZ + 7, GLASS);
box(165, 6, stZ + 18, 165, 8, stZ + 22, GLASS);
box(165, 11, stZ + 10, 165, 11, stZ + 19, GOLD);

// Station sign
block(170, 14, stZ + 12, GLOW);
block(175, 14, stZ + 12, GLOW);

// --- Station platform (on -Z side of track, clear of track) ---
for (let x = 75; x <= 165; x++) {
  for (let dz = LZ - 12; dz <= LZ - 3; dz++) {
    box(x, 2, dz, x, 3, dz, OAK);
  }
}
for (let x = 75; x <= 165; x++) {
  box(x, 3, LZ - 13, x, 3, LZ - 13, BRICKS);
}
for (let x = 85; x <= 155; x += 12) {
  cylZ(x, 4, LZ - 8, 1, 10, OAK_LOG);
}
box(80, 14, LZ - 12, 160, 14, LZ - 3, OAK);
box(80, 15, LZ - 10, 160, 15, LZ - 5, RED_WOOL);

// Walkway from platform area to station building
for (let x = 165; x <= 185; x++) {
  for (let dz = LZ - 3; dz <= stZ; dz++) {
    box(x, 2, dz, x, 2, dz, OAK);
  }
}

// --- Steam clouds (intentionally floating) ---
sphere(front + 14, 26, Z, 3, WHITE);
sphere(front + 17, 29, Z - 1, 2, WHITE);
sphere(front + 20, 31, Z, 2, WHITE);
sphere(front + 16, 33, Z + 1, 2, WHITE);
sphere(front + 22, 28, Z - 2, 1, WHITE);
sphere(front + 13, 30, Z + 2, 2, WHITE);
sphere(front + 19, 34, Z - 1, 1, WHITE);
sphere(front + 25, 30, Z + 1, 1, WHITE);

// --- Boiler detail bands ---
for (let dx = -1; dx <= 1; dx++) {
  for (let dz = -1; dz <= 1; dz++) {
    box(LX - 5, 12 + dx, Z + dz, LX - 5, 12 + dx, Z + dz, GOLD);
    box(LX + 5, 12 + dx, Z + dz, LX + 5, 12 + dx, Z + dz, GOLD);
  }
}

// --- Cab roof trim (sits on cab at y=top=22, within cab footprint, BLACK to connect) ---
for (let dx = -4; dx <= 4; dx++) {
  for (let dz = -4; dz <= 4; dz++) {
    box(back + 1 + dx, top, Z + dz, back + 1 + dx, top, Z + dz, BLACK);
  }
}

// --- Gravel detail ---
for (let x = 55; x <= 205; x++) {
  for (let dz = -5; dz <= 5; dz++) {
    if ((x * 7 + dz * 13) % 5 === 0) {
      box(x, YG + 1, LZ + dz, x, YG + 1, LZ + dz, STONE);
    }
  }
}

// --- Rocks (on ground: y=1) ---
sphere(70, 1, 115, 2, STONE);
sphere(175, 1, 110, 1, STONE);
sphere(155, 1, 160, 2, STONE);
